import { path, FileSystem } from '@servicenow/sdk-build-core'

export function createDirIfNotExists(dirPath: string, fs: FileSystem) {
    if (!FileSystem.existsSync(fs, dirPath)) {
        fs.mkdirSync(dirPath, { recursive: true })
    }
}

/**
 * Finds the first package.json in the path
 * Copied from 'find-root' package to remove direct dependency on 'fs'
 * @param start path to start from
 * @param fs FileSystem
 * @returns path to first package.json in path
 */
export function findRoot(start: string | string[], fs: FileSystem): string {
    if (typeof start === 'string') {
        start = path.normalize(start)
        if (start[start.length - 1] !== path.sep) {
            start += path.sep
        }
        start = start.split(path.sep)
    }
    if (!start.length) {
        throw new Error('package.json not found in path')
    }
    start.pop()
    const dir = start.join(path.sep)
    try {
        if (FileSystem.existsSync(fs, path.join(dir, 'package.json'))) {
            return dir
        }
    } catch (e) {
        // Ignore
    }
    return findRoot(start, fs)
}
